-- One-use MFA recovery codes. Raw codes are generated by the application and never stored.
ALTER TABLE onishield.operator_mfa_audit
  DROP CONSTRAINT operator_mfa_audit_action_check;
ALTER TABLE onishield.operator_mfa_audit
  ADD CONSTRAINT operator_mfa_audit_action_check
  CHECK (action IN (
    'enrollment_started','enabled','disabled','login_verified','step_up',
    'recovery_codes_issued','recovery_login','recovery_step_up'
  ));

CREATE TABLE onishield.operator_mfa_recovery_codes (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  operator_id UUID NOT NULL REFERENCES onishield.operators(id) ON DELETE CASCADE,
  code_hash TEXT NOT NULL UNIQUE CHECK (code_hash ~ '^[a-f0-9]{64}$'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  used_at TIMESTAMPTZ
);
CREATE INDEX operator_mfa_recovery_operator_idx
  ON onishield.operator_mfa_recovery_codes(operator_id,used_at);
REVOKE ALL ON onishield.operator_mfa_recovery_codes FROM PUBLIC,onishield_app,onishield_auth;

DROP FUNCTION onishield.activate_operator_mfa(TEXT,BIGINT);
CREATE FUNCTION onishield.activate_operator_mfa(
  p_session_hash TEXT,p_counter BIGINT,p_recovery_hashes TEXT[]
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,onishield AS $$
DECLARE trusted RECORD;
  unique_hashes INTEGER;
BEGIN
  IF p_session_hash !~ '^[a-f0-9]{64}$' OR p_counter<0
     OR cardinality(p_recovery_hashes)<>10
     OR array_position(p_recovery_hashes,NULL) IS NOT NULL THEN
    RETURN FALSE;
  END IF;
  SELECT count(DISTINCT value) INTO unique_hashes
    FROM unnest(p_recovery_hashes) AS value
   WHERE value ~ '^[a-f0-9]{64}$';
  IF unique_hashes<>10 THEN RETURN FALSE; END IF;

  SELECT s.operator_id INTO trusted
    FROM onishield.operator_sessions s
    JOIN onishield.operators o ON o.id=s.operator_id
    JOIN onishield.operator_memberships m
      ON m.id=s.membership_id AND m.tenant_id=s.tenant_id AND m.operator_id=s.operator_id
   WHERE s.token_hash=p_session_hash AND s.revoked_at IS NULL AND s.expires_at>NOW()
     AND o.status='active' AND m.status='active'
   FOR UPDATE OF s;
  IF NOT FOUND THEN RETURN FALSE; END IF;

  UPDATE onishield.operator_mfa_credentials SET
    active_ciphertext=pending_ciphertext,active_nonce=pending_nonce,active_tag=pending_tag,
    pending_ciphertext=NULL,pending_nonce=NULL,pending_tag=NULL,pending_expires_at=NULL,
    enabled_at=NOW(),last_totp_counter=p_counter,updated_at=NOW()
   WHERE operator_id=trusted.operator_id AND pending_ciphertext IS NOT NULL
     AND pending_expires_at>NOW() AND enabled_at IS NULL;
  IF NOT FOUND THEN RETURN FALSE; END IF;

  INSERT INTO onishield.operator_mfa_recovery_codes(operator_id,code_hash)
    SELECT trusted.operator_id,value FROM unnest(p_recovery_hashes) AS hashes(value);
  INSERT INTO onishield.operator_mfa_audit(operator_id,action)
    VALUES(trusted.operator_id,'enabled'),(trusted.operator_id,'recovery_codes_issued');
  RETURN TRUE;
END;
$$;

CREATE FUNCTION onishield.consume_operator_login_challenge_with_recovery(
  p_challenge_hash TEXT,p_recovery_hash TEXT,p_session_hash TEXT,p_session_expires TIMESTAMPTZ
) RETURNS TABLE(session_id UUID)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,onishield AS $$
DECLARE challenge RECORD;
BEGIN
  IF p_challenge_hash !~ '^[a-f0-9]{64}$' OR p_recovery_hash !~ '^[a-f0-9]{64}$'
     OR p_session_hash !~ '^[a-f0-9]{64}$' OR p_session_expires<=NOW()
     OR p_session_expires>NOW()+INTERVAL '8 hours' THEN
    RAISE EXCEPTION 'Invalid MFA recovery request';
  END IF;
  SELECT * INTO challenge FROM onishield.operator_login_challenges
   WHERE token_hash=p_challenge_hash AND consumed_at IS NULL AND expires_at>NOW()
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invalid MFA challenge'; END IF;

  UPDATE onishield.operator_mfa_recovery_codes
     SET used_at=NOW()
   WHERE operator_id=challenge.operator_id AND code_hash=p_recovery_hash AND used_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invalid or used MFA recovery code'; END IF;

  UPDATE onishield.operator_login_challenges SET consumed_at=NOW()
   WHERE token_hash=p_challenge_hash AND consumed_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'MFA challenge already consumed'; END IF;

  INSERT INTO onishield.operator_mfa_audit(operator_id,action)
    VALUES(challenge.operator_id,'recovery_login');
  RETURN QUERY
    INSERT INTO onishield.operator_sessions
      (tenant_id,operator_id,membership_id,token_hash,expires_at)
    VALUES(challenge.tenant_id,challenge.operator_id,challenge.membership_id,
           p_session_hash,p_session_expires)
    RETURNING id;
END;
$$;

CREATE FUNCTION onishield.mark_operator_session_step_up_with_recovery(
  p_token_hash TEXT,p_recovery_hash TEXT
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER
SET search_path=pg_catalog,onishield AS $$
DECLARE trusted RECORD;
BEGIN
  IF p_token_hash !~ '^[a-f0-9]{64}$' OR p_recovery_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN FALSE;
  END IF;
  SELECT s.id,s.operator_id INTO trusted
    FROM onishield.operator_sessions s
    JOIN onishield.operators o ON o.id=s.operator_id
    JOIN onishield.operator_memberships m
      ON m.id=s.membership_id AND m.tenant_id=s.tenant_id AND m.operator_id=s.operator_id
   WHERE s.token_hash=p_token_hash AND s.revoked_at IS NULL AND s.expires_at>NOW()
     AND o.status='active' AND m.status='active'
   FOR UPDATE OF s;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM onishield.operator_mfa_credentials
     WHERE operator_id=trusted.operator_id AND enabled_at IS NOT NULL
  ) THEN RETURN FALSE; END IF;

  UPDATE onishield.operator_mfa_recovery_codes SET used_at=NOW()
   WHERE operator_id=trusted.operator_id AND code_hash=p_recovery_hash AND used_at IS NULL;
  IF NOT FOUND THEN RETURN FALSE; END IF;

  UPDATE onishield.operator_sessions SET step_up_at=NOW() WHERE id=trusted.id;
  INSERT INTO onishield.operator_mfa_audit(operator_id,action)
    VALUES(trusted.operator_id,'recovery_step_up');
  RETURN TRUE;
END;
$$;

REVOKE ALL ON FUNCTION onishield.activate_operator_mfa(TEXT,BIGINT,TEXT[]) FROM PUBLIC;
REVOKE ALL ON FUNCTION onishield.consume_operator_login_challenge_with_recovery(TEXT,TEXT,TEXT,TIMESTAMPTZ) FROM PUBLIC;
REVOKE ALL ON FUNCTION onishield.mark_operator_session_step_up_with_recovery(TEXT,TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION onishield.activate_operator_mfa(TEXT,BIGINT,TEXT[]) TO onishield_auth;
GRANT EXECUTE ON FUNCTION onishield.consume_operator_login_challenge_with_recovery(TEXT,TEXT,TEXT,TIMESTAMPTZ) TO onishield_auth;
GRANT EXECUTE ON FUNCTION onishield.mark_operator_session_step_up_with_recovery(TEXT,TEXT) TO onishield_auth;
